import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { formatTaskId } from './id.js'
import { EMPTY_REGISTRY, type TaskRecord, type TaskRegistry, type TaskSource } from './types.js'
import type { Lane } from '../config/schema.js'
import type { DuplicateRisk, RiskZone } from './types.js'

export class RegistryStore {
  private registryPath: string
  private data: TaskRegistry

  constructor(basePath: string, registryFile: string) {
    this.registryPath = resolve(basePath, registryFile)
    this.data = this.load()
  }

  private load(): TaskRegistry {
    if (!existsSync(this.registryPath)) {
      return { ...EMPTY_REGISTRY, tasks: {} }
    }

    const raw = readFileSync(this.registryPath, 'utf-8')
    return JSON.parse(raw) as TaskRegistry
  }

  save(): void {
    const dir = dirname(this.registryPath)
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true })
    }
    writeFileSync(this.registryPath, JSON.stringify(this.data, null, 2) + '\n')
  }

  createTask(params: {
    source: TaskSource
    lane: Lane
    riskZone: RiskZone
    branchName: string
    expectedClasses: string[]
    duplicateRisk: DuplicateRisk
  }): TaskRecord {
    const taskId = formatTaskId(this.data.nextTaskNumber)
    this.data.nextTaskNumber++

    const task: TaskRecord = {
      taskId,
      source: params.source,
      lane: params.lane,
      riskZone: params.riskZone,
      branchName: params.branchName,
      prNumber: null,
      expectedClasses: params.expectedClasses,
      duplicateRisk: params.duplicateRisk,
      abandoned: false,
      createdAt: new Date().toISOString(),
      notes: [],
    }

    this.data.tasks[taskId] = task
    this.save()
    return task
  }

  getTask(taskId: string): TaskRecord | undefined {
    return this.data.tasks[taskId]
  }

  getAllTasks(): TaskRecord[] {
    return Object.values(this.data.tasks)
  }

  getActiveTasks(): TaskRecord[] {
    return this.getAllTasks().filter((t) => !t.abandoned)
  }

  getActiveTasksByLane(lane: Lane): TaskRecord[] {
    return this.getActiveTasks().filter((t) => t.lane === lane)
  }

  updateTask(taskId: string, updates: Partial<Pick<TaskRecord, 'prNumber' | 'abandoned' | 'notes' | 'duplicateRisk'>>): TaskRecord {
    const task = this.data.tasks[taskId]
    if (!task) {
      throw new Error(`Task not found: ${taskId}`)
    }

    Object.assign(task, updates)
    this.save()
    return task
  }

  addNote(taskId: string, note: string): void {
    const task = this.data.tasks[taskId]
    if (!task) {
      throw new Error(`Task not found: ${taskId}`)
    }
    task.notes.push(note)
    this.save()
  }

  getNextTaskNumber(): number {
    return this.data.nextTaskNumber
  }

  hasTaskForSource(sourceType: TaskSource['type'], sourceId: string): boolean {
    return this.getActiveTasks().some(
      (t) => t.source.type === sourceType && t.source.id === sourceId
    )
  }
}
